import { defineComponent } from 'vue';
import { default as Leaderboard } from './leaderboard/leaderboard.vue';
import { default as TournamentList } from './tournament-list/tournament-list.vue';
import { default as PrizeList } from './prize-list/prize-list.vue';
import { default as TournamentHistory } from './tournament-history/tournament-history.vue';
import { default as PrizeLeagueOverlays } from './overlays/overlays.vue';
import { PrizeLeagueManager } from '../../services/prize-league/prize-league-manager';
import { getPrizeLeagueSkinName, getPrizeLeagueManager } from './prize-league-utils';
import { userModel } from '../../models/user';
import { inversifyContainer } from '../../inversify/container';

export type PrizeLeaguePanel = 'tournamentList' | 'prizeList' | 'leaderboard' | 'history';

export default defineComponent({
    name: 'PrizeLeague',
    components: {
        Leaderboard,
        PrizeList,
        TournamentList,
        TournamentHistory,
        PrizeLeagueOverlays
    },
    props: {
        visible: {
            type: Boolean,
            default: true
        }
    },
    data() {
        return {
            activePanel: 'tournamentList' as PrizeLeaguePanel,
            activeTournamentID: '' as string | null,
            skinName: getPrizeLeagueSkinName(),
            timerSeconds: 0,
            timerEndAt: null as number | null,
            timerInterval: null as ReturnType<typeof setInterval> | null,
            showInfoOverlay: false
        };
    },
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        activeTournament() {
            return this.prizeLeagueManager.activeTournament.value;
        },
        userData() {
            return this.prizeLeagueManager.userData.value;
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        },
        formattedTime(): string {
            const s = this.timerSeconds;
            const h = Math.floor(s / 3600);
            const m = Math.floor((s % 3600) / 60);
            const sec = s % 60;
            return [h, m, sec].map(v => String(v).padStart(2, '0')).join(':');
        },
        isOverlayActive(): boolean {
            return this.prizeLeagueManager.isCalculatingResults.value
                || this.prizeLeagueManager.tournamentResult.value !== null;
        }
    },
    watch: {
        'activeTournament.secondsToEnd'(newVal: number) {
            if (newVal !== undefined) {
                this.timerEndAt = Date.now() + newVal * 1000;
                this.timerSeconds = newVal;

                // Start the interval if it wasn't running yet
                if (!this.timerInterval) {
                    this.timerInterval = setInterval(() => {
                        this.syncTimer();
                    }, 500);
                    document.addEventListener('visibilitychange', this.onVisibilityChange);
                }
            } else {
                this.timerEndAt = null;
                this.timerSeconds = 0;
                if (this.timerInterval) {
                    clearInterval(this.timerInterval);
                    this.timerInterval = null;
                }
                document.removeEventListener('visibilitychange', this.onVisibilityChange);
            }
        },
        'activeTournament.isOptedIn'(newVal: boolean) {
            // When the player opts in to the active tournament, navigate to the leaderboard.
            // This is handled here (in the parent) rather than in BottomPanel because the
            // v-if on BottomPanel unmounts it before its emit can be received.
            if (newVal && this.activePanel === 'prizeList' && this.activeTournamentID) {
                this.changePanel('leaderboard', this.activeTournamentID);
            }
        }
    },
    mounted() {
        // Check if user is in an active tournament and navigate to leaderboard
        if (this.activeTournament?.isOptedIn) {
            this.activeTournamentID = this.activeTournament.tournamentId;
            this.activePanel = 'leaderboard';
            this.prizeLeagueManager.setCurrentlyViewedTournament(this.activeTournament.tournamentId);
            this.prizeLeagueManager.fetchLeaderboard(this.activeTournament.tournamentId);
        }

        // Auto-open the info panel the first time this user encounters Prize League
        const seenKey = `prize-league-info-seen-${userModel.userId}`;
        if (!localStorage.getItem(seenKey) && this.prizeLeagueManager.tournamentList.value.length > 0) {
            this.showInfoOverlay = true;
            localStorage.setItem(seenKey, '1');
        }

        if (this.activeTournament?.secondsToEnd !== undefined) {
            this.timerEndAt = Date.now() + this.activeTournament.secondsToEnd * 1000;
            this.timerSeconds = this.activeTournament.secondsToEnd;
            this.timerInterval = setInterval(() => {
                this.syncTimer();
            }, 500);
            document.addEventListener('visibilitychange', this.onVisibilityChange);
        }
    },
    unmounted() {
        if (this.timerInterval) {
            clearInterval(this.timerInterval);
            this.timerInterval = null;
        }
        document.removeEventListener('visibilitychange', this.onVisibilityChange);
    },
    methods: {
        syncTimer() {
            this.timerSeconds = Math.max(0, Math.round(((this.timerEndAt ?? Date.now()) - Date.now()) / 1000));
        },
        onVisibilityChange() {
            if (document.visibilityState === 'visible') {
                this.syncTimer();
            }
        },
        changePanel(panel: PrizeLeaguePanel, tournamentID?: string) {
            // Block navigation while overlay is active
            if (this.isOverlayActive) return;

            this.activePanel = panel;
            if (panel === 'tournamentList') {
                this.prizeLeagueManager.onReturnToTournamentList();
                this.prizeLeagueManager.clearCurrentlyViewedTournament();
            } else if (tournamentID !== undefined) {
                this.activeTournamentID = tournamentID;
                this.prizeLeagueManager.setCurrentlyViewedTournament(tournamentID);
                this.prizeLeagueManager.fetchLeaderboard(tournamentID);
            }
        },
        onResultsDismissed() {
            this.activePanel = 'tournamentList';
        }
    }
});